from odoo import fields, models
from odoo.exceptions import UserError


class AccountMove(models.Model):
    """A journal entry generated by payroll stays what payroll made it."""

    _inherit = 'account.move'

    webvue_payroll_origin = fields.Selection(
        [('run', 'Payroll run'), ('payment', 'Payroll payment'), ('eos_provision', 'End of service provision')],
        string='Payroll origin', copy=False, readonly=True, index='btree_not_null',
        help='What generated the entry, like origin_payment_id for a payment entry.',
    )

    def _webvue_refuse_payroll_change(self):
        if self.filtered('webvue_payroll_origin'):
            raise UserError(self.env._('A journal entry generated by payroll cannot be reset, cancelled or deleted.'))

    def button_draft(self):
        self._webvue_refuse_payroll_change()
        return super().button_draft()

    def button_cancel(self):
        self._webvue_refuse_payroll_change()
        return super().button_cancel()

    def unlink(self):
        self._webvue_refuse_payroll_change()
        return super().unlink()
